// @ts-ignore
const tls = require('tls');

const triggerData = $('Email Trigger (IMAP)').item.json;
const uid = triggerData.attributes?.uid || triggerData.id;

const host = process.env.IMAP_HOST || "imap.gmail.com";
const port = Number(process.env.IMAP_PORT || 993);
const user = process.env.IMAP_USER || "thom1.lableigne@gmail.com";
const pass = process.env.IMAP_PASSWORD || "YOUR_IMAP_APP_PASSWORD";

function sendImapCommand(commands) {
  return new Promise((resolve, reject) => {
    let output = '';
    let cmdIndex = 0;

    const socket = tls.connect({
      host: host,
      port: port,
      rejectUnauthorized: false
    }, () => {});

    socket.setEncoding('utf8');

    socket.on('data', (data) => {
      output += data;
      if (cmdIndex < commands.length && (data.includes('* OK') || data.includes(`A${cmdIndex} OK`))) {
        cmdIndex++;
        if (cmdIndex <= commands.length) {
          socket.write(`A${cmdIndex} ${commands[cmdIndex - 1]}\r\n`);
        }
      } else if (data.includes(`A${commands.length} OK`)) {
        socket.end();
        resolve(output);
      } else if (data.includes('NO') || data.includes('BAD')) {
        socket.end();
        reject(new Error(`IMAP Error: ${data}`));
      }
    });

    socket.on('error', (err) => reject(err));

    socket.setTimeout(5000, () => {
      socket.destroy();
      reject(new Error('IMAP connection timed out'));
    });
  });
}

// Pour supprimer dans Gmail : on copie dans la Corbeille puis on retire de l'INBOX
const imapSteps = [
  `LOGIN "${user}" "${pass}"`,
  `SELECT "INBOX"`,
  `UID COPY ${uid} "[Gmail]/Corbeille"`,
  `UID STORE ${uid} +FLAGS (\\Deleted)`,
  `EXPUNGE`,
  `LOGOUT`
];

await sendImapCommand(imapSteps);

return { json: { status: 'deleted_to_trash', uid: uid } };

