const items = $input.all();

return items.map((item) => {
  let raw = item.json.text || item.json.output || JSON.stringify(item.json);
  raw = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    return {
      json: {
        categorie_finale: 'URGENT',
        confiance: 0,
        raison_escalade: 'JSON invalide du modèle léger',
        raw_output: raw
      }
    };
  }

  let categorie = (parsed.categorie || 'URGENT').toUpperCase().trim();
  const confiance = Number(parsed.confiance || 0);

  // Garde-fou : en cas de doute (< 80) ou SPAM peu sûr (< 92), on bascule sur URGENT (donc qwen3:14b)
  if (confiance < 80 || (categorie === 'SPAM' && confiance < 92) || categorie === 'AUTRE') {
    categorie = 'URGENT';
  }

  return {
    json: {
      ...parsed,
      categorie_finale: categorie
    }
  };
});

